import { z } from "zod";

/**
 * Centralized, lazily-validated environment configuration.
 *
 * Env is validated on first access (not at import time) so that pages/routes
 * which don't need a given group — e.g. the public landing page or the health
 * check — keep working even before every secret is provisioned. Each group is
 * validated independently and the result is cached.
 */

const coreSchema = z.object({
  /** Public origin of THIS app, e.g. https://integratrip.example.com (no trailing slash). */
  APP_BASE_URL: z
    .string()
    .url()
    .transform((v) => v.replace(/\/$/, "")),
  /** Base URL of the course Authorization Server. */
  AS_BASE_URL: z
    .string()
    .url()
    .default("https://tarea1-auth-z2fqxmm2ja-uc.a.run.app")
    .transform((v) => v.replace(/\/$/, "")),
});

const dbSchema = z.object({
  DATABASE_URL: z.string().min(1, "DATABASE_URL is required"),
});

const cryptoSchema = z.object({
  /** 32-byte key, base64-encoded, used for AES-256-GCM at-rest encryption. */
  ENCRYPTION_KEY: z.string().min(1, "ENCRYPTION_KEY is required"),
  /** Secret used to sign the session cookie (HMAC). */
  SESSION_SECRET: z.string().min(16, "SESSION_SECRET must be >= 16 chars"),
});

const loginSchema = z.object({
  /** Realm used for app login (per AS docs this is `pre`). */
  APP_LOGIN_REALM: z.string().default("pre"),
  /** Pre-registered client created in the AS /console, reused for login + Andes Air. */
  PRE_CLIENT_ID: z.string().min(1, "PRE_CLIENT_ID is required"),
  PRE_CLIENT_SECRET: z.string().min(1, "PRE_CLIENT_SECRET is required"),
});

function parse<T extends z.ZodType>(schema: T, group: string): z.infer<T> {
  const result = schema.safeParse(process.env);
  if (!result.success) {
    const issues = result.error.issues
      .map((i) => `${i.path.join(".")}: ${i.message}`)
      .join("; ");
    throw new Error(`Invalid environment (${group}): ${issues}`);
  }
  return result.data;
}

let _core: z.infer<typeof coreSchema> | undefined;
let _db: z.infer<typeof dbSchema> | undefined;
let _crypto: z.infer<typeof cryptoSchema> | undefined;
let _login: z.infer<typeof loginSchema> | undefined;

export const coreEnv = () => (_core ??= parse(coreSchema, "core"));
export const dbEnv = () => (_db ??= parse(dbSchema, "db"));
export const cryptoEnv = () => (_crypto ??= parse(cryptoSchema, "crypto"));
export const loginEnv = () => (_login ??= parse(loginSchema, "login"));

/** The exact redirect_uri registered with the AS. Single callback for login + all MCP flows. */
export const redirectUri = () => `${coreEnv().APP_BASE_URL}/callback`;

/** Public URL of the CIMD client-metadata document (also used as the client_id). */
export const clientMetadataDocumentUrl = () =>
  `${coreEnv().APP_BASE_URL}/oauth/client-metadata.json`;

/** Issuer URL of the realm used for app login. */
export const loginIssuer = () => `${coreEnv().AS_BASE_URL}/realms/${loginEnv().APP_LOGIN_REALM}`;

/** Shared JWKS endpoint for validating access tokens (RS256). */
export const jwksUrl = () => `${coreEnv().AS_BASE_URL}/.well-known/jwks.json`;

